<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}

final class Migration {
 static function verifySnapshot(\PDO $db,string $path):array {
  $data=[];$f=gzopen($path,'rb');if(!$f)throw new Problem('Snapshot indisponibil.');gzgets($f);try{while(($line=gzgets($f))!==false){$r=json_decode($line,true,512,JSON_THROW_ON_ERROR);if(in_array($r['table'],['v3_documents','v3_decisions','v3_payment_claims','v3_shipment_claims'],true))$data[$r['table']][]=$r['row'];}}finally{gzclose($f);}$docs=array_column($data['v3_documents']??[],null,'id');$checks=0;
  foreach(['v3_payment_claims'=>'netopia','v3_shipment_claims'=>'fan'] as $table=>$kind)foreach($data[$table]??[] as $claim){$doc=$docs[$claim['resource_id']]??null;if(!$doc)throw new Problem('Document lipsă în rezervarea istorică.');$payload=json_decode($doc['payload'],true);$key=$kind==='netopia'?$payload['external_id']:$payload['awb'];$invoice=$claim['invoice_id']===null?null:($docs[$claim['invoice_id']]['external_id']??null);$sql=$kind==='netopia'?'SELECT r.resolution AS status,i.invoice_number FROM payment_resolutions r JOIN netopia_payments p ON p.id=r.payment_id LEFT JOIN invoices i ON i.id=r.invoice_id WHERE p.canonical_external_id=?':'SELECT r.assignment_status AS status,i.invoice_number FROM shipment_assignments r JOIN fan_shipments p ON p.id=r.shipment_id LEFT JOIN invoices i ON i.id=r.invoice_id WHERE p.awb=?';$current=one($db,$sql,[$key]);if(!$current||$current['status']!==$claim['status']||$current['invoice_number']!==$invoice)throw new Problem('O rezervare istorică diferă după migrare. Instalarea nu se activează.');$checks++;}
  foreach($data['v3_decisions']??[] as $old){$current=one($db,'SELECT * FROM decisions WHERE legacy_reference=?',['v3_decisions:'.$old['id']]);$proof=$current?json_decode($current['source_hashes_json'],true):[];if(!$current||($proof['legacy_payload']??null)!==json_decode($old['payload'],true)||$current['legacy_actor']!==$old['actor']||(int)$current['active']!==(int)$old['active']||$current['created_at']!==$old['created_at'])throw new Problem('O decizie istorică diferă după migrare. Instalarea nu se activează.');$checks++;}return ['relations_and_decisions_verified'=>$checks];
 }
 static function dto(string $kind,array $p):array{return match($kind){
  'order'=>['id'=>(string)$p['order_id'],'order_date'=>$p['order_date'],'payment_date'=>$p['payment_date'],'amount_cents'=>(int)$p['amount_cents'],'awb'=>$p['awb']?:null,'customer_type'=>$p['customer_type'],'client'=>$p['client'],'company'=>$p['company'],'payment_method'=>$p['payment_method'],'transaction_identifier'=>$p['transaction_id']?:null],
  'payment'=>['id'=>(string)$p['external_id'],'client'=>$p['client'],'operation_date'=>$p['operation_date'],'transfer_date'=>$p['payment_date'],'operation_number'=>$p['operation_number'],'gross_amount_cents'=>(int)$p['amount_cents'],'commission'=>$p['commission'],'vat'=>$p['vat']],
  'shipment'=>['id'=>(string)$p['awb'],'awb_date'=>$p['awb_date'],'recipient'=>$p['recipient'],'content'=>$p['content']??'','delivery_status_raw'=>$p['delivery_status']??'','cash_due_cents'=>$p['amount_cents']===null?null:(int)$p['amount_cents'],'transfer_date'=>$p['transfer_date'],'service_raw'=>$p['service_original']??''],
  'invoice'=>['id'=>(string)$p['nr_doc'],'invoice_date'=>$p['data_doc'],'client'=>$p['client'],'amount_cents'=>(int)$p['value_cents'],'balance_cents'=>(int)$p['rest_cents'],'comisionar'=>$p['comisionar']??'','workplace'=>$p['eu_punct_lucru']??'','observation'=>$p['obs_txt']??'']};}
 static function run(\PDO $db,string $path):array {
  if(PHP_SAPI!=='cli'&&(!defined('PLATI_INSTALL')||PLATI_INSTALL!==true))throw new Problem('Migrarea se execută numai din instalatorul securizat sau CLI.',403);$meta=json_decode(file_get_contents($path.'.meta.json'),true,512,JSON_THROW_ON_ERROR);$sha=hash_file('sha256',$path);if(!hash_equals($meta['sha256'],$sha))throw new Problem('Backup cu hash diferit.');if(one($db,"SELECT id FROM import_files WHERE source='legacy' AND file_sha256=?",[$sha]))throw new Problem('Backup deja migrat.');
  $data=[];$counts=[];$f=gzopen($path,'rb');$header=json_decode(gzgets($f),true,512,JSON_THROW_ON_ERROR);if($header['format']!=='plati-goldendrinks-1')throw new Problem('Format backup necunoscut.');while(($line=gzgets($f))!==false){$r=json_decode($line,true,512,JSON_THROW_ON_ERROR);$counts[$r['table']]=($counts[$r['table']]??0)+1;$data[$r['table']][]=$r['row'];}gzclose($f);foreach($meta['rows'] as $t=>$n)if(($counts[$t]??0)!==$n)throw new Problem('Număr de rânduri diferit în backup.');
  return transaction($db,function()use($db,$data,$sha,$path){query($db,'INSERT INTO import_files(source,filename,file_sha256,private_archive_reference,contract_version,status,summary_json,created_at) VALUES(\'legacy\',?,?,?,?,\'applying\',\'{}\',UTC_TIMESTAMP())',[basename($path),$sha,$path,'legacy-v3']);$import=(int)$db->lastInsertId();$map=[];$invoiceLegacy=[];$orderNatural=[];$current=[];$userMap=[];$driverMap=[];
   foreach($data['app_users']??[] as $u){$existing=one($db,'SELECT id FROM users WHERE username=?',[$u['username']]);if(!$existing){query($db,'INSERT INTO users(username,password_hash,display_name,role,enabled) VALUES(?,?,?,?,?)',[$u['username'],$u['password_hash'],$u['display_name'],$u['role'],(int)($u['active']??$u['enabled']??1)]);$userMap[(string)$u['id']]=(int)$db->lastInsertId();}else $userMap[(string)$u['id']]=(int)$existing['id'];}
   $allDocs=array_column($data['v3_documents'],null,'id');$archived=0;$position=0;$kinds=['order'=>'site','shipment'=>'fan','payment'=>'netopia','invoice'=>'omc'];foreach($kinds as $legacyKind=>$kind)foreach($data['v3_documents'] as $d){if($d['kind']!==$legacyKind)continue;$p=json_decode($d['payload'],true,512,JSON_THROW_ON_ERROR);if($legacyKind==='shipment'&&($p['courier']??'fan')!=='fan'){audit($db,'legacy_retired_module_document',['document'=>$d]);$archived++;continue;}$r=self::dto($legacyKind,$p);$rid=Store::importRow($db,$import,'legacy-current',++$position,$d['external_id'],$d['content_hash']);$saved=Store::upsert($db,$kind,$r,$rid,null,$kind==='omc'?'accepted':null);$map[(string)$d['id']]=['kind'=>$kind,'id'=>$saved['id'],'external'=>$r['id']];$current[(string)$d['id']]=$d;if($kind==='omc')$invoiceLegacy[(string)$d['legacy_id']]=$saved['id'];if($kind==='site')$orderNatural[$r['id']]=$saved['id'];query($db,'INSERT INTO migration_map(snapshot_sha256,legacy_table,legacy_key,target_table,target_id,legacy_payload_sha256) VALUES(?,?,?,?,?,?)',[$sha,'v3_documents',(string)$d['id'],Store::TABLE[$kind],$saved['id'],$d['content_hash']]);}
   foreach($data['v3_versions'] as $v){$d=$allDocs[(string)$v['document_id']]??null;if(!$d)throw new Problem('Versiune cu document nemigrat.');$rid=Store::importRow($db,$import,'legacy-versions',++$position,$d['external_id'],$v['content_hash']);query($db,'INSERT INTO source_versions(source_type,source_key,revision,content_hash,source_json,import_row_id,recorded_at) VALUES(?,?,?,?,?,?,?)',['legacy:'.$d['kind'],$d['external_id'],(int)$v['revision'],$v['content_hash'],$v['payload'],$rid,$v['created_at']]);}
   $decisions=[];foreach($data['v3_decisions'] as $v){$r=$map[(string)$v['resource_id']]??null;$i=$v['invoice_id']!==null?($map[(string)$v['invoice_id']]??null):null;if(!$r||($v['invoice_id']!==null&&!$i))throw new Problem('Decizie cu document lipsă.');$payload=json_decode($v['payload'],true);$id=decision($db,$v['action'],['invoice'=>$i['id']??null,$r['kind']==='fan'?'shipment':'payment'=>$r['id']],['legacy_payload'=>$payload,'legacy_source_hash'=>$v['resource_hash'],'legacy_invoice_hash'=>$v['invoice_hash']],$payload['reason']??'Decizie explicită păstrată din aplicația anterioară.',['legacy_actor'=>$v['actor']],'migrate-decision:'.$v['id'],$payload['accepted_difference_cents']??null,'v3_decisions:'.$v['id']);query($db,'UPDATE decisions SET active=?,created_at=? WHERE id=?',[(int)$v['active'],$v['created_at'],$id]);$decisions[(string)$v['id']]=$id;
    $alias=$payload['external_id']??null;if($r['kind']==='netopia'&&$alias&&$alias!==$r['external']&&!one($db,'SELECT payment_id FROM payment_identifiers WHERE provider=\'NETOPIA\' AND external_id=?',[$alias]))query($db,'INSERT INTO payment_identifiers(provider,external_id,payment_id,status,proof_json) VALUES(?,?,?,\'approved\',?)',['NETOPIA',$alias,$r['id'],json(['legacy_decision'=>$v['id'],'legacy_payload'=>$payload])]);}
   $payments=0;$shipments=0;foreach(['v3_payment_claims'=>'netopia','v3_shipment_claims'=>'fan'] as $table=>$kind)foreach($data[$table] as $c){$resource=$map[(string)$c['resource_id']]??null;$invoice=$c['invoice_id']!==null?($map[(string)$c['invoice_id']]??null):null;if(!$resource||($c['invoice_id']!==null&&!$invoice))throw new Problem('Rezervare cu document lipsă.');$did=isset($decisions[(string)($c['decision_id']??'')])?$decisions[(string)$c['decision_id']]:decision($db,'confirmed',['invoice'=>$invoice['id']??null,$kind==='fan'?'shipment':'payment'=>$resource['id']],['legacy_claim'=>$c],'Rezervare existentă păstrată la migrare.',['legacy_actor'=>'istoric'],'migrate-claim:'.$kind.':'.$c['resource_id']);if($kind==='netopia'){query($db,'INSERT INTO payment_resolutions(payment_id,invoice_id,resolution,decision_id) VALUES(?,?,?,?)',[$resource['id'],$invoice['id']??null,$c['status'],$did]);$payments++;}else{query($db,'INSERT INTO shipment_assignments(shipment_id,invoice_id,primary_slot,assignment_status,decision_id) VALUES(?,?,1,?,?)',[$resource['id'],$invoice['id'],$c['status'],$did]);$shipments++;}}
   foreach($data['invoice_order_links']??[] as $l){$i=$invoiceLegacy[(string)$l['invoice_id']]??null;$o=$orderNatural[(string)$l['order_id']]??null;if(!$i||!$o)throw new Problem('Legătură de comandă nemigrată.');$did=decision($db,'link_order',['invoice'=>$i,'order'=>$o],['legacy_link'=>$l],'Legătură comandă–factură păstrată din versiunea 3.0.',['legacy_actor'=>'istoric'],'migrate-order:'.$l['invoice_id']);query($db,'INSERT INTO invoice_orders(invoice_id,order_id,document_role,decision_id) VALUES(?,?,\'original\',?)',[$i,$o,$did]);}
   foreach($data['v3_drivers']??[] as $d){query($db,'INSERT INTO gpd_drivers(name,enabled) VALUES(?,?)',[$d['name'],(int)$d['active']]);$driverMap[$d['id']]=(int)$db->lastInsertId();}foreach($data['v3_deliveries']??[] as $v){$order=$map[(string)$v['order_document_id']]??null;$driver=$driverMap[$v['driver_id']]??null;if(!$order||!$driver)throw new Problem('Livrare GPD cu referințe lipsă.');$did=decision($db,'gpd_delivery',['order'=>$order['id']],['legacy_delivery'=>$v],'Livrare GPD păstrată la migrare.',['legacy_actor'=>'istoric'],'migrate-delivery:'.$v['order_document_id']);query($db,'INSERT INTO gpd_deliveries(order_id,driver_id,delivery_date,decision_id) VALUES(?,?,?,?)',[$order['id'],$driver,$v['delivery_date'],$did]);}
   foreach($data['settings']??[] as $s)if(str_starts_with($s['setting_key'],'invoice_payment_method:')){$nr=substr($s['setting_key'],23);$i=one($db,'SELECT id FROM invoices WHERE invoice_number=?',[$nr]);if($i)query($db,'INSERT INTO invoice_preferences(invoice_id,payment_method,reason) VALUES(?,?,?) ON DUPLICATE KEY UPDATE payment_method=VALUES(payment_method)',[$i['id'],$s['setting_value']==='GPD.ro'?'GPD':$s['setting_value'],'Metodă explicită păstrată din aplicația anterioară.']);}
   foreach($data['omc_pool']??[] as $pool){$p=json_decode($pool['payload'],true);$r=self::dto('invoice',$p);$rid=Store::importRow($db,$import,'legacy-pool',++$position,$r['id'],$pool['content_hash']);Store::upsert($db,'omc',$r,$rid,null,$pool['status']==='internal'?'internal':'outside');}
   foreach($data['omc_cash_links']??[] as $c){audit($db,'legacy_cash_case',['legacy'=>$c]);if($c['status']!=='confirmed'||!$c['storno_nr']||!$c['reissued_nr'])continue;$i=$invoiceLegacy[(string)$c['invoice_id']]??null;$s=one($db,'SELECT id FROM invoices WHERE invoice_number=?',[$c['storno_nr']]);$r=one($db,'SELECT id FROM invoices WHERE invoice_number=?',[$c['reissued_nr']]);if(!$i||!$s||!$r)throw new Problem('Dovadă internă confirmată lipsă.');$did=decision($db,'gpd_cash',['invoice'=>$i],['legacy'=>$c],'Circuit GPD numerar confirmat, păstrat din istoric.',['legacy_actor'=>$c['actor']],'migrate-cash:'.$c['invoice_id']);query($db,'INSERT INTO cash_circuits(original_invoice_id,storno_invoice_id,reissued_invoice_id,status,decision_id) VALUES(?,?,?,\'confirmed\',?)',[$i,$s['id'],$r['id'],$did]);}
   foreach($data['v3_drafts']??[] as $d){$u=one($db,'SELECT id FROM users WHERE username=?',[$d['actor']]);if($d['status']==='draft'&&$u){query($db,'INSERT INTO review_batches(actor_id,status,revision,result_json) VALUES(?,\'legacy_draft\',?,?)',[$u['id'],(int)$d['revision'],json(['legacy_id'=>$d['id'],'payload'=>json_decode($d['payload'],true),'requires_revalidation'=>true])]);}audit($db,'legacy_draft_preserved',['legacy'=>$d]);}
   // Raw legacy audit/reference decisions/refunds remain immutable in the private audit.
   foreach(['v3_events','audit_log','activity_log','order_events','site_status_history','audit_attribution','link_evidence','order_reference_decisions','fan_refunds','import_summaries','site_order_conflicts','netopia_settlements','netopia_settlement_transactions','netopia_bank_rows'] as $table)foreach($data[$table]??[] as $r)audit($db,'legacy:'.$table,['row'=>$r]);
   $result=['documents'=>count($map),'retired_module_documents_archived'=>$archived,'legacy_versions'=>count($data['v3_versions']),'legacy_decisions'=>count($decisions),'payment_reservations'=>$payments,'shipment_reservations'=>$shipments,'order_links'=>count($data['invoice_order_links']),'drivers'=>count($driverMap),'snapshot_sha256'=>$sha,'sources_absent_from_future_export_retained'=>true];query($db,'UPDATE import_files SET status=\'completed\',summary_json=? WHERE id=?',[json($result),$import]);audit($db,'legacy_migration_completed',$result);return $result;
  });
 }
